      en: ["1965: Year the national park was established.", "1,412 km²: Total area of the protected sanctuary.", "Asiatic lions: Only home of this species in the world.", "7 rivers: Vital water sources flow through the park.", "Teak forests: These cover half of the total area.", "300+ species: Number of birds recorded in the forest."],
      es: ["1965: Año de fundación del parque nacional.", "1412 km²: Superficie total del área protegida.", "Leones asiáticos: Único hogar de esta especie en el mundo.", "7 ríos: Masas de agua vitales atraviesan el parque.", "Bosques de teca: Cubren la mitad de la superficie.", "Más de 300 especies: Numerosas especies de aves documentadas."],
      pt: ["1965: Ano de fundação do parque nacional.", "1412 km²: Área total da reserva.", "Leões asiáticos: Único lar desta espécie no mundo.", "7 rios: Corpos de água vitais atravessam o parque.", "Florestas de teca: Estas cobrem metade da área.", "300+ espécies: Numerosas espécies de aves documentadas."],
      fr: ["1965 : Année de fondation du parc national.", "1 412 km² : Superficie totale de la zone protégée.", "Lions d'Asie : Seul habitat au monde pour cette espèce.", "7 rivières : Des cours d'eau vitaux traversent le parc.", "Forêts de teck : Elles couvrent la moitié de la surface.", "300+ espèces : De nombreuses espèces d'oiseaux documentées."],
