      es: ["1936: Año de fundación como Parque Nacional Hailey.", "520 km²: Tamaño del área central del núcleo.", "Project Tiger: Se inició aquí en el año 1973.", "600+: Número de especies de aves que viven allí.", "488: Especies de plantas catalogadas en la reserva.", "Primero: El parque nacional más antiguo en suelo indio."],
      pt: ["1936: Ano de fundação como Parque Nacional Hailey.", "520 km²: Tamanho da área central do núcleo.", "Project Tiger: Iniciou-se aqui no ano de 1973.", "600+: Número de espécies de aves que lá vivem.", "488: Espécies de plantas catalogadas na reserva.", "Primeiro: O parque nacional mais antigo em solo indiano."],
      fr: ["1936 : Année de fondation sous le nom de parc national de Hailey.", "520 km² : Taille de la zone centrale (cœur du parc).", "Project Tiger : Lancé ici en 1973.", "600+ : Nombre d'espèces d'oiseaux y vivant.", "488 : Espèces végétales répertoriées dans la réserve.", "Premier : Le plus ancien parc national sur le sol indien."],
