      es: ["Patrimonio de la Humanidad por la UNESCO.", "Hogar de animales raros como el oso negro asiático y el baral o carnero azul."],
      pt: ["Património Mundial da UNESCO.", "Lar de animais raros, como o urso-negro-asiático e o bharal."],
