      ro: ["Izvorăște din Ghatii de Vest din Maharashtra.", "Un râu sacru în hinduism.", "Se varsă în Golful Bengal."],
      en: ["Rises in the Western Ghats of Maharashtra.", "A sacred river in Hinduism.", "Flows into the Bay of Bengal."],
      es: ["Nace en los Ghats occidentales de Maharashtra.", "Un río sagrado en el hinduismo.", "Fluye hacia el golfo de Bengala."],
