    descriptionAdvanced: {
      de: "Die Godavari ist nach dem Ganges der zweitlängste Fluss Indiens und wird aufgrund ihrer religiösen und geografischen Bedeutung oft als Dakshin Ganga oder Ganges des Südens bezeichnet. Sie entspringt in Trimbakeshwar im Bundesstaat Maharashtra, in den Westghats, und fließt über eine Strecke von etwa 1465 Kilometern in östlicher Richtung, bevor sie in den Golf von Bengalen mündet. Der Fluss durchquert mehrere Bundesstaaten, darunter Telangana, Andhra Pradesh und Odisha, und entwässert ein riesiges Becken, das etwa 10 % der Fläche Indiens ausmacht. Entlang seiner Ufer befinden sich zahlreiche heilige Stätten, und alle zwölf Jahre findet in Nashik das bedeutende Kumbh-Mela-Fest statt. Die Godavari ist eine lebenswichtige Ressource für die Landwirtschaft und Energieerzeugung in Süd- und Zentralindien, steht jedoch vor Herausforderungen wie Wasserknappheit und Verschmutzung. Ihr Delta ist bekannt für seine fruchtbaren Böden und beherbergt bedeutende Mangrovenwälder und Feuchtgebiete.",
      hu: "A Godavari a Gangesz után India második leghosszabb folyója, amelyet vallási és földrajzi jelentősége miatt gyakran Dakshin Ganga-nak, vagyis a dél Gangeszének neveznek. A Maharashtra állambeli Trimbakeshwarban, a Nyugati-Ghatokban ered, és mintegy 1465 kilométeren keresztül folyik keleti irányba, mielőtt a Bengáli-öbölbe torkollik. A folyó több államon halad keresztül, köztük Telanganán, Andhra Pradeshen és Odishán, vízgyűjtő területe pedig India felszínének mintegy 10%-át teszi ki. Partjai mentén számos szent hely található, Nashik városában pedig tizenkét évente megrendezik a nagyszabású Kumbh Mela fesztivált. A Godavari létfontosságú erőforrás a mezőgazdaság és az energiatermelés számára Dél- és Közép-Indiában, de olyan kihívásokkal néz szembe, mint a vízhiány és a szennyezés. Deltája termékeny talajáról ismert, és jelentős mangroveerdőknek, valamint vizes élőhelyeknek ad otthont.",
      ro: "Fluviul Godavari este al doilea cel mai lung curs de apă din India, după Gange, și este adesea supranumit Dakshin Ganga sau Gangele Sudului datorită importanței sale religioase și geografice. Izvorăște la Trimbakeshwar în statul Maharashtra, în Munții Ghats de Vest, și parcurge o distanță de aproximativ 1465 de kilometri spre est înainte de a se vărsa în Golful Bengal. Fluviul traversează mai multe state, inclusiv Telangana, Andhra Pradesh și Odisha, drenând un bazin uriaș care reprezintă circa 10% din suprafața Indiei. Malurile sale sunt punctate de numeroase locuri sfinte, iar orașul Nashik găzduiește celebrul festival Kumbh Mela o dată la doisprezece ani. Godavari este o resursă vitală pentru agricultură și producția de energie în sudul și centrul Indiei, deși se confruntă cu probleme precum deficitul de apă și poluarea. Delta sa este renumită pentru solurile fertile și adăpostește ecosisteme importante de mangrove.",
      en: "The Godavari is India's second longest river after the Ganges and is often referred to as Dakshin Ganga or the Ganges of the South due to its immense religious and geographical significance. It originates at Trimbakeshwar in the state of Maharashtra, within the Western Ghats, and flows for approximately 1,465 kilometers in an easterly direction before emptying into the Bay of Bengal. The river traverses several states, including Telangana, Andhra Pradesh, and Odisha, draining a massive basin that covers about 10% of India's total land area. Numerous sacred sites line its banks, and the city of Nashik hosts the significant Kumbh Mela festival every twelve years. The Godavari is a vital resource for agriculture and power generation in southern and central India, though it faces challenges such as water scarcity and pollution. Its delta is known for its fertile soil and hosts important mangrove forests and diverse wetland ecosystems.",
      es: "El Godavari es, después del Ganges, el segundo río más largo de la India y, debido a su importancia religiosa y geográfica, a menudo se le llama Dakshin Ganga o Ganges del Sur. Nace en Trimbakeshwar, en el estado de Maharashtra, en los Ghats occidentales, y fluye unos 1.465 kilómetros en dirección este antes de desembocar en el golfo de Bengala. El río atraviesa varios estados, incluidos Telangana, Andhra Pradesh y Odisha, y drena una enorme cuenca que representa aproximadamente el 10% de la superficie de la India. A lo largo de sus orillas se encuentran numerosos lugares sagrados, y cada doce años se celebra en Nashik el importante festival Kumbh Mela. El Godavari es un recurso vital para la agricultura y la generación de energía en el sur y el centro de la India, pero se enfrenta a retos como la escasez de agua y la contaminación. Su delta es conocido por sus suelos fértiles y alberga importantes manglares y humedales.",
      pt: "O Godavari é, depois do Ganges, o segundo rio mais longo da Índia e, devido à sua importância religiosa e geográfica, é frequentemente chamado de Dakshin Ganga ou Ganges do Sul. Nasce em Trimbakeshwar, no estado de Maharashtra, nos Gates Ocidentais, e flui por uma distância de cerca de 1.465 quilômetros em direção leste antes de desaguar no Golfo de Bengala. O rio atravessa vários estados, incluindo Telangana, Andhra Pradesh e Odisha, e drena uma enorme bacia que representa cerca de 10% da área da Índia. Ao longo das suas margens encontram-se numerosos locais sagrados, e a cada doze anos realiza-se em Nashik o importante festival Kumbh Mela. O Godavari é um recurso vital para a agricultura e produção de energia no sul e centro da Índia, mas enfrenta desafios como a escassez de água e a poluição. O seu delta é conhecido pelos seus solos férteis e abriga importantes manguezais e zonas húmidas.",
      fr: "Le Godavari est le deuxième plus long fleuve d'Inde après le Gange et, en raison de son importance religieuse et géographique, il est souvent appelé Dakshin Ganga ou le Gange du Sud. Il prend sa source à Trimbakeshwar, dans l'État du Maharashtra, dans les Ghats occidentaux, et parcourt environ 1 465 kilomètres vers l'est avant de se jeter dans le golfe du Bengale. Le fleuve traverse plusieurs États, dont le Telangana, l'Andhra Pradesh et l'Odisha, et draine un immense bassin représentant environ 10 % de la superficie de l'Inde. De nombreux sites sacrés jalonnent ses rives, et le célèbre festival de la Kumbh Mela se tient à Nashik tous les douze ans. Le Godavari est une ressource vitale pour l'agriculture et la production d'énergie dans le sud et le centre de l'Inde, bien qu'il soit confronté à des défis tels que la pénurie d'eau et la pollution. Son delta est réputé pour ses sols fertiles et abrite d'importantes forêts de mangroves et zones humides.",
    },
